async function run(){
  // set current page to workspace
  const page = figma.getNodeById('4:2');
  if(!page){ throw new Error('workspace page not found'); }
  await figma.setCurrentPageAsync(page);

  // load fonts
  const weights = ['Regular','Medium','SemiBold','Bold','ExtraBold'];
  for(const w of weights){
    await figma.loadFontAsync({family:'Nunito', style:w}).catch(e=>console.log('font err '+w));
  }

  // media asset node ids
  const coins = [
    ['2:8','Coin_BTC'],['2:11','Coin_ETH'],['2:14','Coin_USDT'],['2:17','Coin_BNB'],
    ['2:20','Coin_USDC'],['2:23','Coin_BUSD'],['2:26','Coin_XRP'],['2:29','Coin_DOGE'],
    ['2:32','Coin_ADA'],['2:35','Coin_MATIC'],['2:38','Coin_DAI'],['2:41','Coin_AVAX'],
    ['2:44','Coin_CAKE'],['2:47','Coin_MANA'],['2:50','Coin_MKR'],['2:53','Coin_NEAR'],
    ['2:56','Coin_DASH'],['2:59','Coin_ETC']
  ];
  const icons = [
    ['2:75','Icon_Send'],['2:80','Icon_Receive'],['2:85','Icon_Add'],['2:95','Icon_Scan'],
    ['2:100','Icon_Search'],['2:106','Icon_Face_ID'],['2:112','Icon_Swap'],['2:118','Icon_Backspace'],
    ['2:123','Icon_Back'],['2:128','Icon_Close']
  ];
  const avatar = [['2:65','Avatar_Neutral']];
  const shell = [['3:26','StatusBar'],['3:36','HomeIndicator']];

  // build a bank frame to hold cloned assets
  let bank = figma.createFrame();
  bank.name = 'Media Assets (cloned bank)';
  bank.x = 1400; bank.y = 0;
  bank.resize(1200, 2200);
  bank.fills = [];

  let created = {};
  let cx = 0, cy = 0;
  async function place(nodeId, name){
    let src = figma.getNodeById(nodeId);
    if(!src){ console.log('missing '+name); return; }
    let inst = null;
    try { inst = src.createInstance(); } catch(e){ console.log('inst err '+name+' '+e.message); }
    if(!inst){ try { inst = src.clone(); } catch(e){ console.log('clone err'); } }
    if(inst){
      inst.name = name;
      inst.x = cx; inst.y = cy;
      bank.appendChild(inst);
      created[name]= inst.id;
      cx += 80;
      if(cx > 1100){ cx = 0; cy += 100; }
    }
  }

  for(const [id,n] of coins.length? coins.concat(icons,avatar,shell) : []){ await place(id,n); }

  console.log(JSON.stringify({bank: bank.id, created}));
}
