  bank.resize(900, 2200);

  const media = {
    'Coin_BTC':'2:8','Coin_ETH':'2:11','Coin_USDT':'2:14','Coin_BNB':'2:17',
    'Coin_USDC':'2:20','Coin_BUSD':'2:23','Coin_XRP':'2:26','Coin_DOGE':'2:29',
    'Coin_ADA':'2:32','Coin_MATIC':'2:35','Coin_DAI':'2:38','Coin_AVAX':'2:41',
    'Coin_CAKE':'2:44','Coin_MANA':'2:47','Coin_MKR':'2:50','Coin_NEAR':'2:53',
    'Coin_DASH':'2:56','Coin_ETC':'2:59','Avatar_Neutral':'2:65',
    'Icon_Send':'2:75','Icon_Receive':'2:80','Icon_Add':'2:85','Icon_Scan':'2:95',
    'Icon_Search':'2:100','Icon_Face_ID':'2:106','Icon_Swap':'2:112',
    'Icon_Backspace':'2:118','Icon_Back':'2:123','Icon_Close':'2:128'
  };
  async function grab(id, x, y){
    const n = figma.getNodeById(id);
    if(!n){ return null; }
    let inst;
    if(n.clone){ inst = n.clone(); } else { inst = n; }
    inst.x = x; inst.y = y;
    bank.appendChild(inst);
    return inst;
  }
  let x=0,y=0,col=0;
  for(const key in media){
    const inst = await grab(media[key], x, y);
    if(inst) inst.name = key;
    col++;
    if(col%12===0){ x=0; y+=80; } else { x+=80; }
  }
  ws.appendChild(bank);
  return 'assets bank built';
}
