  function tSet(t,s){t.fontSize=s.size||14;t.fontName={family:'Nunito',style:s.w||'Regular'};t.fills=[{type:'SOLID',color:hex(s.c||'1A1C26'),opacity:s.o??1}];t.x=s.x||0;t.y=s.y||0;t.textAutoResize='WIDTH_AND_HEIGHT';}
