async function run(){
  const ws = figma.root.children.find(p=>p.name==='03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  const out=[];
  // Test font loading one by one, catching errors
  const styles=['Regular','Medium','Semi Bold','SemiBold','Bold','Extra Bold','ExtraBold'];
  for(const s of styles){
    try{ await figma.loadFontAsync({family:'Nunito',style:s}); out.push(s+':OK'); }
    catch(e){ out.push(s+':FAIL'); }
  }
  // Create test text with Bold (assume works)
  const f=figma.createFrame(); f.name='FontProbe'; f.resize(200,100); f.x=0; f.y=900; ws.appendChild(f);
  try{
    await figma.loadFontAsync({family:'Nunito',style:'Bold'});
    const t=figma.createText(); t.characters='Font Test $54,292.79 +5.21%'; f.appendChild(t);
    t.fontSize=14; t.fontName={family:'Nunito',style:'Bold'};
    out.push('text:OK');
  }catch(e){ out.push('text:FAIL '+e.message); }
  figma.notify(out.join(' | '));
}
