  const sheet = figma.createFrame();
  sheet.name='Sheet'; sheet.resize(375,640); sheet.x=0; sheet.y=172;
  sheet.fills=[{type:'SOLID',color:WHITE}]; sheet.cornerRadius=28;
  frame.appendChild(sheet);

  const grab = figma.createRectangle(); grab.resize(60,4); grab.x=157; grab.y=10; grab.cornerRadius=2; grab.fills=[{type:'SOLID',color:{r:0.9,g:0.91,b:0.93}}]; sheet.appendChild(grab);

  const back = getSym('Icon_Back'); back.name='back'; back.resize(24,24); back.x=16; back.y=16; sheet.appendChild(back);

  const title=figma.createText(); title.characters='Invest to Strategy'; title.fontSize=22; title.fontName={family:'Nunito',style:'Bold'}; title.fills=[{type:'SOLID',color:DARK}]; title.x=52; title.y=38; sheet.appendChild(title);

  const gas=figma.createText(); gas.characters='⛽️ No gas, free investments'; gas.fontSize=13; gas.fontName={family:'Nunito',style:'Regular'}; gas.fills=[{type:'SOLID',color:GREY}]; gas.x=20; gas.y=72; sheet.appendChild(gas);

  const dai=getSym('Coin_DAI'); dai.name='Coin_DAI'; dai.resize(32,32); dai.x=40; dai.y=124; sheet.appendChild(dai);
  const dl=figma.createText(); dl.characters='DAI'; dl.fontSize=18; dl.fontName={family:'Nunito',style:'Semi Bold'}; dl.fills=[{type:'SOLID',color:DARK}]; dl.x=80; dl.y=130; sheet.appendChild(dl);
  const sw=getSym('Icon_Swap'); sw.name='Icon_Swap'; sw.resize(22,22); sw.x=300; sw.y=128; sheet.appendChild(sw);

  const amt=figma.createText(); amt.characters='3,021'; amt.fontSize=44; amt.fontName={family:'Nunito',style:'Extra Bold'}; amt.fills=[{type:'SOLID',color:DARK}]; amt.x=20; amt.y=192; sheet.appendChild(amt);

  const max=figma.createText(); max.characters='Max'; max.fontSize=14; max.fontName={family:'Nunito',style:'Bold'}; max.fills=[{type:'SOLID',color:GRAPHITE}]; max.x=286; max.y=205; sheet.appendChild(max);

  const keys=['1','2','3','4','5','6','7','8','9',',','0',''];
  const subs={1:'',2:'ABC',3:'DEF',4:'GHI',5:'JKL',6:'MNO',7:'PQRS',8:'TUV',9:'WXYZ'};
  let kx=8, ky=268;
  for(let i=0;i<12;i++){
    const kb=figma.createFrame(); kb.name='Key'; kb.resize(112,58); kb.x=kx; kb.y=ky; kb.fills=[{type:'SOLID',color:LIGHT}]; kb.cornerRadius=14; sheet.appendChild(kb);
    if(i===11){
      const bs=getSym('Icon_Backspace'); bs.resize(22,16); bs.x=45; bs.y=21; bs.name='backspace'; kb.appendChild(bs);
    } else {
      const bf=figma.createFrame(); bf.x=20; bf.y=12; bf.resize(72,34); bf.fills=[]; kb.appendChild(bf);
      const kt=figma.createText(); kt.characters=keys[i]; kt.fontSize=22; kt.fontName={family:'Nunito',style:(i%3===0?'Semi Bold':'Regular')}; kt.fills=[{type:'SOLID',color:DARK}]; kt.x=0; kt.y=0; bf.appendChild(kt);
      if(subs[keys[i]]){
        const st=figma.createText(); st.characters=subs[keys[i]]; st.fontSize=7; st.fontName={family:'Nunito',style:'Regular'}; st.fills=[{type:'SOLID',color:GREY}]; st.x=0; st.y=24; bf.appendChild(st);
      }
    }
    kx+=119;
    if((i+1)%3===0){ kx=8; ky+=66; }
  }

  const hold=figma.createFrame(); hold.name='InvestButton'; hold.resize(335,54); hold.x=20; hold.y=566; hold.fills=[{type:'SOLID',color:GRAPHITE}]; hold.cornerRadius=27; sheet.appendChild(hold);
  const face=getSym('Icon_Face_ID'); face.name='Icon_Face_ID'; face.resize(24,24); face.x=62; face.y=15; hold.appendChild(face);
  const ht=figma.createText(); ht.characters='Hold to Invest'; ht.fontSize=17; ht.fontName={family:'Nunito',style:'Bold'}; ht.fills=[{type:'SOLID',color:WHITE}]; ht.x=104; ht.y=16; hold.appendChild(ht);

  const hi=getSym('HomeIndicator'); hi.x=0; hi.y=778; frame.appendChild(hi);

  return 'built '+frame.id;
}
run();
